/**
 * Check if a given object implements the CrossListingsItem interface.
 */
export function instanceOfCrossListingsItem(value) {
    if (!("symbol" in value) || value["symbol"] === undefined)
        return false;
    if (!("name" in value) || value["name"] === undefined)
        return false;
    if (!("exchange" in value) || value["exchange"] === undefined)
        return false;
    if (!("micCode" in value) || value["micCode"] === undefined)
        return false;
    return true;
}
export function CrossListingsItemFromJSON(json) {
    return CrossListingsItemFromJSONTyped(json, false);
}
export function CrossListingsItemFromJSONTyped(json, ignoreDiscriminator) {
    if (json == null) {
        return json;
    }
    return {
        symbol: json["symbol"],
        name: json["name"],
        exchange: json["exchange"],
        micCode: json["mic_code"],
    };
}
export function CrossListingsItemToJSON(json) {
    return CrossListingsItemToJSONTyped(json, false);
}
export function CrossListingsItemToJSONTyped(value, ignoreDiscriminator = false) {
    if (value == null) {
        return value;
    }
    return {
        symbol: value["symbol"],
        name: value["name"],
        exchange: value["exchange"],
        mic_code: value["micCode"],
    };
}
